const staticData = $getWorkflowStaticData('global');
const reviewGate = staticData.reviewGate || {};
const pendingByReviewExecutionProcessId =
  reviewGate.pendingByReviewExecutionProcessId || {};

return $input.all().flatMap((item) => {
  const registration = pendingByReviewExecutionProcessId[item.json.execution?.id || ''];

  if (!registration) {
    return [];
  }

  return [{
    json: {
      reviewExecutionProcessId: item.json.execution.id,
      reviewExecutionStatus: item.json.execution.status || '',
      conversationId: registration.conversationId || item.json.scope?.conversation?.id || '',
      projectId: registration.projectId,
      taskId: registration.taskId,
      workspaceId: registration.workspaceId,
      sourceExecutionProcessId: registration.sourceExecutionProcessId,
      repoIdsJson: registration.repoIdsJson || '[]',
    },
  }];
});

const staticData = $getWorkflowStaticData('global');
const reviewGate = staticData.reviewGate || {};
reviewGate.pendingByReviewExecutionProcessId ??= {};
reviewGate.pendingBySourceExecutionId ??= {};
reviewGate.completedBySourceExecutionId ??= {};
staticData.reviewGate = reviewGate;

const parseRepoIds = (raw) => {
  try {
    const parsed = JSON.parse(raw || '[]');
    return Array.isArray(parsed)
      ? parsed.map((entry) => String(entry)).filter(Boolean)
      : [];
  } catch (error) {
    return [];
  }
};

const extractJsonCandidate = (content) => {
  const trimmed = String(content || '').trim();
  if (!trimmed) {
    return '';
  }

  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced?.[1]) {
    return fenced[1].trim();
  }

  const start = trimmed.indexOf('{');
  const end = trimmed.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    return trimmed.slice(start, end + 1);
  }

  return trimmed;
};

const parseDecision = (content) => {
  const candidate = extractJsonCandidate(content);
  const parsed = JSON.parse(candidate);

  if (typeof parsed?.approved === 'boolean') {
    return {
      approved: parsed.approved,
      reasoning: String(parsed.reasoning || '').trim() || 'Reviewer returned no reasoning.',
    };
  }

  if (typeof parsed?.needs_attention === 'boolean') {
    return {
      approved: !parsed.needs_attention,
      reasoning: String(parsed.reasoning || '').trim() || 'Reviewer returned no reasoning.',
    };
  }

  throw new Error('reviewer verdict must include either approved or needs_attention as a boolean');
};

const transcript = JSON.parse($json.transcriptJson || '{"messages":[]}');
const messages = Array.isArray(transcript?.messages) ? transcript.messages : [];
const reviewerMessages = messages.filter((message) => (
  message?.role === 'assistant' &&
  (!message.execution_process_id || message.execution_process_id === $json.reviewExecutionProcessId)
));
const finalReviewerMessage = reviewerMessages.at(-1);

let decision;
if ($json.reviewExecutionStatus !== 'completed') {
  decision = {
    approved: false,
    reasoning: `Reviewer execution finished with status ${$json.reviewExecutionStatus}.`,
  };
} else if (!finalReviewerMessage?.content) {
  decision = {
    approved: false,
    reasoning: 'Reviewer execution completed without an assistant verdict.',
  };
} else {
  try {
    decision = parseDecision(finalReviewerMessage.content);
  } catch (error) {
    decision = {
      approved: false,
      reasoning: `Failed to parse reviewer verdict: ${error.message}`,
    };
  }
}

const repoIds = parseRepoIds($json.repoIdsJson);
if (decision.approved && repoIds.length === 0) {
  decision = {
    approved: false,
    reasoning: 'Reviewer approved the work, but no workspace repositories were captured for merge.',
  };
}

reviewGate.completedBySourceExecutionId[$json.sourceExecutionProcessId] = {
  reviewExecutionProcessId: $json.reviewExecutionProcessId,
  approved: decision.approved,
  reviewedAt: new Date().toISOString(),
};
delete reviewGate.pendingBySourceExecutionId[$json.sourceExecutionProcessId];
delete reviewGate.pendingByReviewExecutionProcessId[$json.reviewExecutionProcessId];

return {
  json: {
    taskId: $json.taskId,
    workspaceId: $json.workspaceId,
    sourceExecutionProcessId: $json.sourceExecutionProcessId,
    reviewExecutionProcessId: $json.reviewExecutionProcessId,
    approved: decision.approved,
    needsAttention: !decision.approved,
    reasoning: decision.reasoning,
    repoIdsJson: JSON.stringify(repoIds),
  },
};

return $input.all().flatMap((item) => {
  if (!item.json.approved) {
    return [];
  }

  const repoIds = JSON.parse(item.json.repoIdsJson || '[]');
  if (!Array.isArray(repoIds)) {
    return [];
  }

  return repoIds
    .map((repoId) => String(repoId).trim())
    .filter(Boolean)
    .map((repoId) => ({
      json: {
        workspaceId: item.json.workspaceId,
        repoId,
      },
    }));
});
